1	import { spawn } from "node:child_process";
2	import { chmodSync, existsSync, mkdirSync, readFileSync, unlinkSync, writeFileSync } from "node:fs";
3	import { homedir } from "node:os";
4	import { join, resolve } from "node:path";
5	import { createInterface } from "node:readline";
6	import YAML from "yaml";
7	import { detectFormat, fingerprint, listingPayload, signBytes, verifyPack } from "@runlog/rules-schema";
8	
9	/**
10	 * The command line, as somebody.
11	 *
12	 * `runlog login` signs in the way a terminal can: it asks WorkOS for a short
13	 * code, shows it with a link, and waits while you confirm it in a browser:
14	 * the OAuth device flow, against a WorkOS application of the CLI's own. What
15	 * comes back is a session: an access token that lasts an hour and a refresh
16	 * token that renews it, kept in the user's config directory, mode 600, and
17	 * renewed here without anyone noticing. Signing out forgets it.
18	 *
19	 * A machine with no browser and nobody at it, CI publishing a release, has
20	 * no way to confirm a code, so a key made on the profile page does instead:
21	 * `RUNLOG_API_KEY` in the environment, or `runlog login --key` pasted once.
22	 * Either way, every command that talks to the API sends what it has as the
23	 * bearer and the API tells the two apart.
24	 *
25	 * `claim` proves a signing key is the account's: the API hands out a nonce,
26	 * this signs it with the private key, and the API records the fingerprint
27	 * under the account, from then on the app names the account beside that
28	 * signature. `publish` puts a pack in the account's library, the same call
29	 * sync makes. `sign` and `issue` ask the API whether the key is claimed
30	 * before they sign, and refuse if not. Signing is arithmetic and a fork of
31	 * this file can always do the arithmetic; what an account buys is the right
32	 * to be named when the pack is opened, and the refusal is what keeps a name
33	 * on a signature meaning something.
34	 */
35	
36	const DEFAULT_API = "https://runlog.scrthq.com/api";
37	/** Renew an access token this close to its expiry rather than risk a 401 mid-command. */
38	const RENEW_MARGIN_MS = 60_000;
39	const DEVICE_GRANT = "urn:ietf:params:oauth:grant-type:device_code";
40	
41	export interface Session {
42	  clientId: string;
43	  issuer: string;
44	  accessToken: string;
45	  refreshToken: string;
46	  /** When the access token stops working, ISO. */
47	  expiresAt: string;
48	}
49	
50	export interface Credentials {
51	  api: string;
52	  /** A key from the profile page: CI's way in, or `login --key`. */
53	  key?: string;
54	  /** A session from `runlog login`: the browser's way in, from a terminal. */
55	  session?: Session;
56	  savedAt: string;
57	}
58	
59	function configDir(): string {
60	  const base =
61	    process.env["RUNLOG_CONFIG_DIR"] ??
62	    (process.platform === "win32"
63	      ? join(process.env["APPDATA"] ?? join(homedir(), "AppData", "Roaming"), "runlog")
64	      : join(process.env["XDG_CONFIG_HOME"] ?? join(homedir(), ".config"), "runlog"));
65	  return base;
66	}
67	
68	const credentialsPath = () => join(configDir(), "credentials.json");
69	
70	/** What is saved, or what the environment says: RUNLOG_API_KEY wins, for CI. */
71	export function credentials(): Credentials | null {
72	  const fromEnv = process.env["RUNLOG_API_KEY"];
73	  if (fromEnv) return { api: process.env["RUNLOG_API"] ?? DEFAULT_API, key: fromEnv, savedAt: "" };
74	  try {
75	    const raw = JSON.parse(readFileSync(credentialsPath(), "utf8")) as Partial<Credentials>;
76	    if (typeof raw.api !== "string") return null;
77	    if (typeof raw.key === "string") return { api: raw.api, key: raw.key, savedAt: raw.savedAt ?? "" };
78	    const s = raw.session;
79	    if (s && typeof s.accessToken === "string" && typeof s.refreshToken === "string" && typeof s.clientId === "string") {
80	      return {
81	        api: raw.api,
82	        session: {
83	          clientId: s.clientId,
84	          issuer: s.issuer ?? WORKOS,
85	          accessToken: s.accessToken,
86	          refreshToken: s.refreshToken,
87	          expiresAt: s.expiresAt ?? "",
88	        },
89	        savedAt: raw.savedAt ?? "",
90	      };
91	    }
92	    return null;
93	  } catch {
94	    return null;
95	  }
96	}
97	
98	function save(creds: Credentials): void {
99	  const dir = configDir();
100	  mkdirSync(dir, { recursive: true });
101	  writeFileSync(credentialsPath(), `${JSON.stringify(creds, null, 2)}\n`, "utf8");
102	  try {
103	    chmodSync(credentialsPath(), 0o600);
104	  } catch {
105	    /* Windows */
106	  }
107	}
108	
109	async function ask(prompt: string, hidden = false): Promise<string> {
110	  const rl = createInterface({ input: process.stdin, output: process.stdout, terminal: true });
111	  return new Promise((done) => {
112	    if (hidden) {
113	      // Echo nothing: the key is a secret, and a terminal scrollback is a log.
114	      const out = process.stdout as NodeJS.WriteStream & { muted?: boolean };
115	      process.stdout.write(prompt);
116	      const original = out.write.bind(out);
117	      out.write = ((chunk: unknown, ...rest: unknown[]) => {
118	        if (typeof chunk === "string" && chunk !== "\n" && chunk !== "\r\n") return true;
119	        return (original as (...a: unknown[]) => boolean)(chunk, ...rest);
120	      }) as typeof out.write;
121	      rl.question("", (answer) => {
122	        out.write = original as typeof out.write;
123	        process.stdout.write("\n");
124	        rl.close();
125	        done(answer.trim());
126	      });
127	    } else {
128	      rl.question(prompt, (answer) => {
129	        rl.close();
130	        done(answer.trim());
131	      });
132	    }
133	  });
134	}
135	
136	/* ---- WorkOS: the device flow and the renewal -------------------------------- */
137	
138	const WORKOS = "https://api.workos.com";
139	
140	/** What a token endpoint answers: tokens on success, an `error` code otherwise. */
141	interface TokenAnswer {
142	  access_token?: string;
143	  refresh_token?: string;
144	  error?: string;
145	  error_description?: string;
146	}
147	
148	/** The bits of the world the flow touches, so a test can hand in its own. */
149	export interface FlowDeps {
150	  fetch: typeof fetch;
151	  sleep: (ms: number) => Promise<void>;
152	  say: (line: string) => void;
153	  /** Try to open a URL in a browser; a failure is quiet, the code is on screen anyway. */
154	  open: (url: string) => void;
155	  now: () => number;
156	}
157	
158	const realDeps: FlowDeps = {
159	  fetch: (input, init) => fetch(input, init),
160	  sleep: (ms) => new Promise((r) => setTimeout(r, ms)),
161	  say: (line) => console.log(line),
162	  open: (url) => {
163	    try {
164	      const [cmd, args] =
165	        process.platform === "win32"
166	          ? ["cmd", ["/c", "start", "", url]]
167	          : process.platform === "darwin"
168	            ? ["open", [url]]
169	            : ["xdg-open", [url]];
170	      spawn(cmd, args, { detached: true, stdio: "ignore" })
171	        .on("error", () => {})
172	        .unref();
173	    } catch {
174	      /* no browser here; the link is printed */
175	    }
176	  },
177	  now: () => Date.now(),
178	};
179	
180	async function postForm(
181	  deps: FlowDeps,
182	  url: string,
183	  form: Record<string, string>,
184	): Promise<{ status: number; body: Record<string, unknown> }> {
185	  const response = await deps.fetch(url, {
186	    method: "POST",
187	    headers: { "content-type": "application/x-www-form-urlencoded", accept: "application/json" },
188	    body: new URLSearchParams(form).toString(),
189	  });
190	  const text = await response.text();
191	  try {
192	    return { status: response.status, body: JSON.parse(text) as Record<string, unknown> };
193	  } catch {
194	    throw new Error(`WorkOS did not answer as expected (${response.status})`);
195	  }
196	}
197	
198	/** When a JWT says it stops working, or a fallback if it does not say. */
199	function expiryOf(accessToken: string, now: number): string {
200	  try {
201	    const payload = JSON.parse(Buffer.from(accessToken.split(".")[1] ?? "", "base64url").toString("utf8")) as { exp?: number };
202	    if (typeof payload.exp === "number") return new Date(payload.exp * 1000).toISOString();
203	  } catch {
204	    /* not a JWT we can read; assume WorkOS's shortest lifetime */
205	  }
206	  return new Date(now + 5 * 60_000).toISOString();
207	}
208	
209	/**
210	 * The device flow, start to finish: ask for a code, show it, poll until the
211	 * person confirms it in a browser or the code dies. Returns the session.
212	 */
213	export async function deviceFlow(clientId: string, issuer: string, deps: FlowDeps = realDeps): Promise<Session> {
214	  const start = await postForm(deps, `${issuer}/user_management/authorize/device`, { client_id: clientId });
215	  const s = start.body as {
216	    device_code?: string;
217	    user_code?: string;
218	    verification_uri?: string;
219	    verification_uri_complete?: string;
220	    expires_in?: number;
221	    interval?: number;
222	    error_description?: string;
223	  };
224	  if (start.status >= 400 || !s.device_code || !s.user_code || !s.verification_uri) {
225	    throw new Error(s.error_description ?? `WorkOS would not start a sign-in (${start.status})`);
226	  }
227	  deps.say("");
228	  deps.say(`  Open  ${s.verification_uri}`);
229	  deps.say(`  Code  ${s.user_code}`);
230	  deps.say("");
231	  deps.say("Waiting for you to confirm it there. Ctrl-C gives up.");
232	  if (s.verification_uri_complete) deps.open(s.verification_uri_complete);
233	
234	  let interval = Math.max(1, s.interval ?? 5);
235	  const deadline = deps.now() + (s.expires_in ?? 300) * 1000;
236	  while (deps.now() < deadline) {
237	    await deps.sleep(interval * 1000);
238	    const poll = await postForm(deps, `${issuer}/user_management/authenticate`, {
239	      grant_type: DEVICE_GRANT,
240	      device_code: s.device_code,
241	      client_id: clientId,
242	    });
243	    const a = poll.body as TokenAnswer;
244	    if (a.access_token && a.refresh_token) {
245	      return {
246	        clientId,
247	        issuer,
248	        accessToken: a.access_token,
249	        refreshToken: a.refresh_token,
250	        expiresAt: expiryOf(a.access_token, deps.now()),
251	      };
252	    }
253	    switch (a.error) {
254	      case "authorization_pending":
255	        continue;
256	      case "slow_down":
257	        interval += 1;
258	        continue;
259	      case "access_denied":
260	        throw new Error("the sign-in was refused in the browser");
261	      case "expired_token":
262	        throw new Error("the code expired before it was confirmed; run `runlog login` again");
263	      default:
264	        throw new Error(a.error_description ?? a.error ?? `WorkOS answered ${poll.status}`);
265	    }
266	  }
267	  throw new Error("the code expired before it was confirmed; run `runlog login` again");
268	}
269	
270	/** A new access token from the refresh token; the refresh token rotates too. */
271	export async function renew(session: Session, deps: FlowDeps = realDeps): Promise<Session> {
272	  const answer = await postForm(deps, `${session.issuer}/user_management/authenticate`, {
273	    grant_type: "refresh_token",
274	    refresh_token: session.refreshToken,
275	    client_id: session.clientId,
276	  });
277	  const a = answer.body as TokenAnswer;
278	  if (!a.access_token || !a.refresh_token) {
279	    throw new Error("your sign-in has lapsed; run `runlog login` again");
280	  }
281	  return { ...session, accessToken: a.access_token, refreshToken: a.refresh_token, expiresAt: expiryOf(a.access_token, deps.now()) };
282	}
283	
284	/* ---- the API, as whoever is signed in ---------------------------------------- */
285	
286	/**
287	 * The bearer to send: the key, or the session's access token, renewed first
288	 * when it is about to lapse. `force` renews regardless, after a 401.
289	 */
290	async function bearer(creds: Credentials, force = false, deps: FlowDeps = realDeps): Promise<string> {
291	  if (creds.key) return creds.key;
292	  if (!creds.session) throw new Error("not signed in: run `runlog login`");
293	  const lapsing = !creds.session.expiresAt || Date.parse(creds.session.expiresAt) - deps.now() < RENEW_MARGIN_MS;
294	  if (!force && !lapsing) return creds.session.accessToken;
295	  const session = await renew(creds.session, deps);
296	  creds.session = session;
297	  if (!process.env["RUNLOG_API_KEY"]) save(creds);
298	  return session.accessToken;
299	}
300	
301	/** One call to the API as whoever is signed in. Throws with the API's own words on a failure. */
302	export async function api<T>(method: string, path: string, body?: unknown): Promise<T> {
303	  const creds = credentials();
304	  if (!creds) throw new Error("not signed in: run `runlog login`");
305	  const once = async (token: string) => {
306	    const response = await fetch(`${creds.api.replace(/\/$/, "")}${path}`, {
307	      method,
308	      headers: { authorization: `Bearer ${token}`, ...(body !== undefined ? { "content-type": "application/json" } : {}) },
309	      ...(body !== undefined ? { body: JSON.stringify(body) } : {}),
310	    });
311	    const text = await response.text();
312	    let parsed: unknown = null;
313	    try {
314	      parsed = JSON.parse(text);
315	    } catch {
316	      throw new Error(`the API at ${creds.api} did not answer as expected (${response.status})`);
317	    }
318	    return { status: response.status, parsed };
319	  };
320	  let answer = await once(await bearer(creds));
321	  // A session's token can be refused between the expiry check and the call;
322	  // renew once and try again before deciding the sign-in is gone.
323	  if (answer.status === 401 && creds.session) answer = await once(await bearer(creds, true));
324	  if (answer.status === 401) {
325	    throw new Error(
326	      creds.key
327	        ? "that key is not accepted; make a new one on your profile page and `runlog login --key` again"
328	        : "your sign-in has lapsed; run `runlog login` again",
329	    );
330	  }
331	  if (answer.status >= 400) {
332	    const said = (answer.parsed as { error?: string } | null)?.error;
333	    throw new Error(said ?? `the API said ${answer.status}`);
334	  }
335	  return answer.parsed as T;
336	}
337	
338	/* ---- commands ---------------------------------------------------------------- */
339	
340	async function greet(apiUrl: string): Promise<void> {
341	  const me = await api<{ profile?: { name?: string; email?: string } }>("GET", "/me");
342	  const who = me.profile?.name ?? me.profile?.email ?? "you";
343	  console.log(`signed in as ${who} at ${apiUrl}`);
344	}
345	
346	export async function cmdLogin(args: string[], deps: FlowDeps = realDeps): Promise<number> {
347	  const apiUrl = (flag(args, "--api") ?? process.env["RUNLOG_API"] ?? DEFAULT_API).replace(/\/$/, "");
348	  if (process.env["RUNLOG_API_KEY"]) {
349	    console.error("RUNLOG_API_KEY is set, so that is what every command will use; unset it to sign in as yourself");
350	    return 1;
351	  }
352	
353	  if (args.includes("--key")) {
354	    console.log("Paste a command-line key from your profile page in Runlog. It is not shown as you type.");
355	    const key = await ask("key: ", true);
356	    if (!key.startsWith("rl_")) {
357	      console.error("that does not look like a Runlog key; they begin with rl_");
358	      return 1;
359	    }
360	    // Prove it before keeping it, so a typo is caught here and not on the next command.
361	    save({ api: apiUrl, key, savedAt: new Date().toISOString() });
362	    try {
363	      await greet(apiUrl);
364	      return 0;
365	    } catch (error) {
366	      unlinkSync(credentialsPath());
367	      console.error(error instanceof Error ? error.message : String(error));
368	      return 1;
369	    }
370	  }
371	
372	  try {
373	    // Which WorkOS application to sign in against is the API's to say.
374	    const response = await deps.fetch(`${apiUrl}/auth/cli`, { headers: { accept: "application/json" } });
375	    const text = await response.text();
376	    let about: { clientId?: string | null; issuer?: string } = {};
377	    try {
378	      about = JSON.parse(text) as typeof about;
379	    } catch {
380	      throw new Error(`the API at ${apiUrl} did not answer as expected (${response.status})`);
381	    }
382	    if (!about.clientId)
383	      throw new Error(`the API at ${apiUrl} cannot sign in a terminal yet; use \`runlog login --key\` with a key from your profile page`);
384	    const session = await deviceFlow(about.clientId, about.issuer ?? WORKOS, deps);
385	    save({ api: apiUrl, session, savedAt: new Date().toISOString() });
386	    await greet(apiUrl);
387	    return 0;
388	  } catch (error) {
389	    console.error(error instanceof Error ? error.message : String(error));
390	    return 1;
391	  }
392	}
393	
394	export function cmdLogout(): number {
395	  const creds = credentials();
396	  if (existsSync(credentialsPath())) {
397	    unlinkSync(credentialsPath());
398	    console.log(creds?.key ? "signed out; the key is still valid until you revoke it on your profile page" : "signed out");
399	  } else {
400	    console.log("not signed in");
401	  }
402	  return 0;
403	}
404	
405	export async function cmdWhoami(): Promise<number> {
406	  try {
407	    const creds = credentials();
408	    const me = await api<{ sub: string; scope?: string; profile?: { name?: string; email?: string } }>("GET", "/me");
409	    const claims = await api<{ claims: Array<{ fingerprint: string }> }>("GET", "/claims");
410	    const how = process.env["RUNLOG_API_KEY"]
411	      ? "with RUNLOG_API_KEY"
412	      : creds?.key
413	        ? "with a key from the profile page"
414	        : "from the browser";
415	    console.log(`${me.profile?.name ?? "(no name)"} <${me.profile?.email ?? "?"}>  ${me.sub}`);
416	    console.log(`signed in ${how} at ${creds?.api ?? DEFAULT_API}${me.scope === "release" ? " (a key that only releases)" : ""}`);
417	    console.log(
418	      claims.claims.length > 0
419	        ? `claimed signing keys: ${claims.claims.map((c) => c.fingerprint).join(", ")}`
420	        : "no claimed signing keys yet: `runlog claim key.json`",
421	    );
422	    return 0;
423	  } catch (error) {
424	    console.error(error instanceof Error ? error.message : String(error));
425	    return 1;
426	  }
427	}
428	
429	interface StoredKey {
430	  publicKey: string;
431	  privateKey: string;
432	  fingerprint: string;
433	}
434	
435	function readKey(path: string): StoredKey {
436	  const key = JSON.parse(readFileSync(resolve(path), "utf8")) as Partial<StoredKey>;
437	  if (!key.privateKey || !key.publicKey) throw new Error(`${path} is not a runlog signing key`);
438	  return { publicKey: key.publicKey, privateKey: key.privateKey, fingerprint: key.fingerprint ?? "" };
439	}
440	
441	export async function cmdClaim(args: string[]): Promise<number> {
442	  const keyPath = args.filter((a) => !a.startsWith("-"))[0];
443	  if (!keyPath) {
444	    console.error("usage: runlog claim key.json");
445	    return 2;
446	  }
447	  try {
448	    const key = readKey(keyPath);
449	    const { nonce } = await api<{ nonce: string }>("POST", "/claims/nonce");
450	    const signature = await signBytes(new TextEncoder().encode(nonce), key.privateKey);
451	    const { claim } = await api<{ claim: { fingerprint: string; name: string | null } }>("POST", "/claims", {
452	      publicKey: key.publicKey,
453	      nonce,
454	      signature,
455	    });
456	    console.log(`claimed ${claim.fingerprint}${claim.name ? ` as ${claim.name}` : ""}`);
457	    console.log("packs signed with this key now show your name in the app");
458	    return 0;
459	  } catch (error) {
460	    console.error(error instanceof Error ? error.message : String(error));
461	    return 1;
462	  }
463	}
464	
465	/**
466	 * Is this key claimed by the signed-in account? `sign` and `issue` refuse
467	 * otherwise, with the command that fixes it.
468	 */
469	export async function requireClaimed(publicKey: string): Promise<void> {
470	  const fp = await fingerprint(publicKey);
471	  const { claims } = await api<{ claims: Array<{ fingerprint: string }> }>("GET", "/claims");
472	  if (!claims.some((c) => c.fingerprint === fp)) {
473	    throw new Error(`this key (${fp}) is not claimed by your account: run \`runlog claim key.json\` first, so the app can name you`);
474	  }
475	}
476	
477	export async function cmdPublish(args: string[]): Promise<number> {
478	  const input = args.filter((a) => !a.startsWith("-"))[0];
479	  if (!input) {
480	    console.error("usage: runlog upload <pack.yaml|pack.json>");
481	    return 2;
482	  }
483	  try {
484	    const path = resolve(input);
485	    const text = readFileSync(path, "utf8");
486	    const format = detectFormat(path);
487	    const doc = (format === "json" ? JSON.parse(text) : YAML.parse(text)) as Record<string, unknown>;
488	    const id = String(doc["id"] ?? "");
489	    if (!id) throw new Error("the pack has no id");
490	    const { createHash } = await import("node:crypto");
491	    const hash = createHash("sha256").update(text).digest("hex").slice(0, 16);
492	    const at = new Date().toISOString();
493	    await api("PUT", `/packs/${encodeURIComponent(id)}`, {
494	      title: String(doc["title"] ?? id),
495	      version: String(doc["version"] ?? ""),
496	      format,
497	      filename: input.split(/[\\/]/).pop(),
498	      importedAt: at,
499	      updatedAt: at,
500	      hash,
501	      source: text,
502	    });
503	    console.log(`uploaded ${id} to your own library, where only you can see it; it reaches your devices on their next sync`);
504	    return 0;
505	  } catch (error) {
506	    console.error(error instanceof Error ? error.message : String(error));
507	    return 1;
508	  }
509	}
510	
511	function flag(args: string[], name: string): string | undefined {
512	  const at = args.indexOf(name);
513	  return at === -1 ? undefined : args[at + 1];
514	}
515	
516	/**
517	 * The price a release is listed at: `--price 3.00` in dollars, `--free`, or
518	 * neither, which keeps whatever the marketplace has. The API takes whole cents.
519	 */
520	export function priceFlag(args: string[]): { amount: number; currency: "usd" } | "free" | "keep" | { error: string } {
521	  if (args.includes("--free")) return "free";
522	  const raw = flag(args, "--price");
523	  if (raw === undefined) return "keep";
524	  const m = /^\$?(\d+)(?:\.(\d{1,2}))?$/.exec(raw.trim());
525	  if (!m) return { error: `--price wants dollars and cents, like 3.00; got ${JSON.stringify(raw)}` };
526	  const cents = Number(m[1]) * 100 + Number((m[2] ?? "0").padEnd(2, "0"));
527	  if (cents < 100 || cents > 100_000) return { error: "--price is from 1.00 to 1000.00" };
528	  return { amount: cents, currency: "usd" };
529	}
530	
531	/**
532	 * A release to the marketplace: the signed pack goes up as the publisher's
533	 * master and is listed, at a price, free, or as it already is. This is what
534	 * a build server runs when a tag is pushed, with RUNLOG_API_KEY set; the
535	 * marketplace seals what you signed and never sees your signing key.
536	 */
537	export async function cmdRelease(args: string[]): Promise<number> {
538	  const input = args.filter((a) => !a.startsWith("-"))[0];
539	  const price = priceFlag(args);
540	  if (!input || (typeof price === "object" && "error" in price)) {
541	    if (typeof price === "object" && "error" in price) console.error(price.error);
542	    console.error("usage: runlog release <pack.yaml|pack.json> [--price 3.00 | --free] [--draft]");
543	    return 2;
544	  }
545	  try {
546	    const path = resolve(input);
547	    const text = readFileSync(path, "utf8");
548	    const format = detectFormat(path);
549	    const raw = (format === "json" ? JSON.parse(text) : YAML.parse(text)) as Record<string, unknown>;
550	    const verified = await verifyPack(raw);
551	    if (verified.status === "unsigned")
552	      throw new Error("the pack is not signed; run `runlog sign` first, since the marketplace seals what you signed");
553	    if (verified.status === "invalid") throw new Error(`the signature does not match the pack (${verified.reason}); sign it again`);
554	    const listing = listingPayload(text, format, raw);
555	    if (!listing.ok) throw new Error(listing.error);
556	    const { pack, payload } = listing;
557	
558	    const me = await api<{ publisher: { name: string } | null }>("GET", "/publishers/me");
559	    if (!me.publisher) throw new Error("this account is not a publisher; become one on your profile page first");
560	
561	    const id = encodeURIComponent(pack.id);
562	    const put = await api<{ pack: { status: string; price: { amount: number; currency: string } | null } }>(
563	      "PUT",
564	      `/publishers/packs/${id}`,
565	      payload,
566	    );
567	    const dollars = (p: { amount: number; currency: string }) => `${p.currency.toUpperCase()} ${(p.amount / 100).toFixed(2)}`;
568	    console.log(`uploaded ${pack.id} v${pack.version} to ${me.publisher.name}`);
569	
570	    if (args.includes("--draft")) {
571	      console.log(
572	        put.pack.status === "listed"
573	          ? "  still listed; the card follows the new version"
574	          : "  kept as a draft; list it with --price or --free",
575	      );
576	      return 0;
577	    }
578	    if (price === "keep") {
579	      if (put.pack.status === "listed") console.log(`  listed ${put.pack.price ? `at ${dollars(put.pack.price)}` : "free"}, as before`);
580	      else console.log("  not listed yet; pass --price 3.00 or --free to put it in the marketplace");
581	      return 0;
582	    }
583	    const listed = await api<{ available?: boolean; error?: string; listing?: { price: "free" | { amount: number; currency: string } } }>(
584	      "POST",
585	      `/publishers/packs/${id}/listing`,
586	      price === "free" ? {} : price,
587	    );
588	    if (listed.available === false) throw new Error(listed.error ?? "selling is not switched on here yet; a free listing works");
589	    const shown = listed.listing?.price;
590	    console.log(`  listed ${shown && shown !== "free" ? `at ${dollars(shown)}` : "free"}`);
591	    return 0;
592	  } catch (error) {
593	    console.error(error instanceof Error ? error.message : String(error));
594	    return 1;
595	  }
596	}
