1	import type { Offer } from "./offer.ts";
2	
3	export interface Press {
4	  from: string;
5	  run: string;
6	  seq: number;
7	  ref: string;
8	  press: string;
9	  move?: string;
10	  answer?: Record<string, unknown>;
11	}
12	
13	export interface Verdict {
14	  ok: boolean;
15	  say?: string;
16	}
17	
18	export interface Acts {
19	  primary: () => void;
20	  move: (id: string) => void;
21	  undo: () => void;
22	  answer: (answer: Record<string, unknown>) => void;
23	}
24	
25	/**
26	 * Whether a press from outside may be taken, and taking it.
27	 *
28	 * Given everything it decides on, because this is the one place a run
29	 * can be moved by something that is not looking at it. Two rules do the
30	 * work. A press names the offer it was drawn from, so one made while
31	 * the unit was closing cannot roll into the next unit. And a press
32	 * names itself and who sent it, so two decks racing for the same button
33	 * each move it once, and one deck retried after an answer that never
34	 * arrived moves it only once.
35	 *
36	 * Not total, though: an `act` may throw, most likely a write raced by
37	 * another device. That still spends the ref and settles a verdict --
38	 * the deck is told the press failed rather than left waiting on one
39	 * that will never answer.
40	 */
41	export function takePress(press: Press, at: { seq: number; offer: Offer; seen: Map<string, Verdict> }, act: Acts): Verdict {
42	  const key = `${press.from}:${press.ref}`;
43	  const already = at.seen.get(key);
44	  if (already) return already;
45	
46	  const settle = (verdict: Verdict): Verdict => {
47	    at.seen.set(key, verdict);
48	    return verdict;
49	  };
50	
51	  if (press.seq !== at.seq) return settle({ ok: false, say: "That moved on." });
52	
53	  /**
54	   * Taking the press itself: a throw is still a press taken, not one left
55	   * hanging. In the act's own words where it threw any, because an act is
56	   * the only thing that can see why -- a list still wanting the page, say.
57	   */
58	  const take = (fn: () => void): Verdict => {
59	    try {
60	      fn();
61	      return { ok: true };
62	    } catch (e) {
63	      const said = e instanceof Error ? e.message.trim() : "";
64	      return { ok: false, say: said === "" ? "That press failed." : said };
65	    }
66	  };
67	
68	  switch (press.press) {
69	    case "primary": {
70	      if (!at.offer.primary) return settle({ ok: false, say: at.offer.needsPage ?? "There is nothing to press." });
71	      return settle(take(() => act.primary()));
72	    }
73	    case "move": {
74	      const id = press.move ?? "";
75	      if (!at.offer.moves.some((m) => m.id === id)) return settle({ ok: false, say: "That is not on offer." });
76	      return settle(take(() => act.move(id)));
77	    }
78	    case "undo": {
79	      if (!at.offer.undo) return settle({ ok: false, say: "There is nothing to take back." });
80	      return settle(take(() => act.undo()));
81	    }
82	    case "answer": {
83	      // Tick everything this step waits for and press its own button. The
84	      // offer says whether there is a list to tick; the act says whether
85	      // one of its boxes is beyond a deck, and throws its own words if so.
86	      if (press.answer?.["ticks"] === "all") {
87	        if (!at.offer.presets.some((p) => p.kind === "checklist")) return settle({ ok: false, say: "The run is not asking for that." });
88	        return settle(take(() => act.answer({ ticks: "all" })));
89	      }
90	      if (!at.offer.presets.some((p) => p.kind === "declareSubject")) return settle({ ok: false, say: "The run is not asking for that." });
91	      if (String(press.answer?.["subject"] ?? "").trim() === "") return settle({ ok: false, say: "That answer was empty." });
92	      return settle(take(() => act.answer(press.answer!)));
93	    }
94	    default:
95	      return settle({ ok: false, say: "This run does not know that press." });
96	  }
97	}
98

