12	/**
13	 * The socket's three moments.
14	 *
15	 * Connect: the token rides in the query string, because a browser's
16	 * WebSocket cannot set a header. It is checked the same way the HTTP API
17	 * checks a bearer, and a bad one is refused before the socket opens.
18	 * Message: the one thing a device says is which session it is watching;
19	 * it must be a member, and a session it may not see is ignored without
20	 * saying whether it exists. Disconnect: the rows go.
21	 *
22	 * A run shared by link admits a socket with no account: `?t=<token>&run=<id>`
23	 * opens a connection that watches that run and nothing else, and says
24	 * nothing it is told.
25	 *
26	 * Nothing else. Moves still travel over HTTP; the socket is a doorbell.
27	 */
28	
29	export interface WsEvent {
30	  requestContext: { routeKey: string; connectionId: string };
31	  queryStringParameters?: Record<string, string | undefined>;
32	  body?: string;
33	  isBase64Encoded?: boolean;
34	}
35	
36	export interface WsDeps {
37	  live: LiveStore;
38	  /** A way to post to connections; absent in a test that only checks routing. */
39	  poster?: Poster;
40	  store: Pick<Store, "getSession" | "streamKeyOwner" | "manifest" | "getSnapshot" | "addAsk" | "updateSession">;
41	  races: Pick<RaceStore, "getRace">;
42	  verify: (authorization: string | undefined) => Promise<Caller>;
43	  now?: () => string;
44	  /**
45	   * Whether this account may drive a run from outside it. Absent where
46	   * plans are off, which is the same answer as yes.
47	   */
48	  entitled?: (sub: string) => Promise<boolean>;
49	}
50	
51	interface WsResult {
52	  statusCode: number;
53	  body?: string;
54	}
55	
56	/**
57	 * A socket opened by something that drives a game rather than draws a
58	 * scoreboard.
59	 *
60	 * It arrives on the same addresses as every other watcher, with the same
61	 * keys, because what it is allowed to see is exactly what a watcher is
62	 * allowed to see. What it asks for in addition is to be told in
63	 * operations, and to say which player it is sitting in front of.
64	 */
65	function attachedOf(event: WsEvent, run: string): { control: true; seat?: string; run: string } | undefined {
66	  if (event.queryStringParameters?.["as"] !== "control") return undefined;
67	  const raw = (event.queryStringParameters?.["seat"] ?? "").trim().slice(0, 40);
68	  return { control: true, ...(raw ? { seat: raw } : {}), run };
69	}
70	
71	/**
72	 * A socket that presses rather than draws.
73	 *
74	 * It signs in as the account, the way the app's own devices do, because
75	 * what it may do is what the owner may do. It names no run at connect: it
76	 * is told which runs are being held, and picks. A link's token and a
77	 * stream key are refused here, which is why this is read only on the
78	 * signed-in branch below.
79	 */
80	function deckOf(event: WsEvent): { deck: true } | undefined {
81	  return event.queryStringParameters?.["as"] === "deck" ? { deck: true } : undefined;
82	}
83	
84	/**
85	 * Whether this watcher is a device that could take a press.
86	 *
87	 * A link's socket and a scene's are not; an attached tool is told in
88	 * operations and writes nothing; a deck is the thing asking. What is
89	 * left is a signed-in device with the run open, which is the page.
90	 */
91	function writes(w: { sub: string; control?: boolean; deck?: boolean }): boolean {
92	  return !w.control && !w.deck && !w.sub.startsWith("public:") && !w.sub.startsWith("stream:");
93	}
94	
95	export async function route(event: WsEvent, deps: WsDeps): Promise<WsResult> {
96	  const { routeKey, connectionId } = event.requestContext;
97	  const now = deps.now ?? (() => new Date().toISOString());
98	  // The socket has no method, only which of its three moments this is.
99	  annotate({ method: "WS", route: routeKey });
100	
101	  /**
102	   * The account's runs that something is holding open.
103	   *
104	   * Not the run that moved most recently, which is all a watch key can
105	   * know: a deck presses, and a press wants a device on the other end.
106	   * The newest twenty are considered, because an account's manifest is
107	   * every run it has ever played and a deck's picker is a short list.
108	   */
109	  const heldRuns = async (sub: string) => {
110	    const { sessions } = await deps.store.manifest(sub);
111	    const mine = sessions
112	      .filter((p) => p.role === "owner" && !p.deletedAt && !p.endedAt)
113	      .sort((a, b) => (a.updatedAt < b.updatedAt ? 1 : a.updatedAt > b.updatedAt ? -1 : 0))
114	      .slice(0, 20);
115	    const held = await Promise.all(mine.map(async (p) => ((await deps.live.watchers(p.id)).some(writes) ? p : null)));
116	    return held
117	      .filter((p): p is (typeof mine)[number] => p !== null)
118	      .map((p) => ({
119	        id: p.id,
120	        ...(p.name ? { name: p.name } : {}),
121	        ...(p.packTitle ? { packTitle: p.packTitle } : {}),
122	        held: true as const,
123	      }));
124	  };
125	
126	  /**
127	   * Said to an account's decks whenever the held set changes, and once on
128	   * connect, which is the same message: a deck comes up before anything is
129	   * running, so a list fetched once would stay empty all evening.
130	   */
131	  const tellDecks = async (sub: string, only?: string): Promise<void> => {
132	    const poster = deps.poster;
133	    if (!poster) return;
134	    // Everything in here, one guard: a deck that cannot be given its list
135	    // right now is still connected and hears the next push. A rejection
136	    // out of `manifest` or `watchers` must not turn a $connect into a 500,
137	    // which would refuse the deck outright.
138	    try {
139	      const decks = only ? [{ connectionId: only }] : await deps.live.decksOf(sub);
140	      if (decks.length === 0) return;
141	      const line = JSON.stringify({ t: "runs", runs: await heldRuns(sub) });
142	      for (const d of decks) {
143	        if ((await poster.post(d.connectionId, line)) === "gone") await deps.live.disconnect(d.connectionId);
144	      }
145	    } catch (error) {
146	      console.error("live: could not say which runs are held", error);
147	    }
148	  };
149	
150	  if (routeKey === "$connect") {
151	    const t = event.queryStringParameters?.["t"];
152	    const run = event.queryStringParameters?.["run"];
153	    if (t && run) {
154	      const session = await deps.store.getSession(run);
155	      if (!session || session.meta.deletedAt || !session.meta.publicTokenHash || hashToken(t) !== session.meta.publicTokenHash)
156	        return { statusCode: 401, body: "not shared" };
157	      const who = `public:${run}`;
158	      const attached = attachedOf(event, run);
159	      await deps.live.connect(connectionId, who, now(), attached);
160	      await deps.live.watch(connectionId, run, who, now(), attached);
161	      return { statusCode: 200 };
162	    }
163	    /**
164	     * A scene's socket, opened on the account's watch key.
165	     *
166	     * The address in a browser source or a bot's client is set up once and
167	     * lives for months, so it cannot name a run: it names the account, and
168	     * this finds the run. Of the runs open to watchers, the one moved most
169	     * recently, which is the one being played.
170	     *
171	     * Which run it watches is settled when it connects. A socket open
172	     * across the start of a new run goes on watching the old one until it
173	     * is opened again; the bot hears `run-ended` on the old one, which is
174	     * the moment to reconnect.
175	     */
176	    const k = event.queryStringParameters?.["k"];
177	    if (k) {
178	      const owner = await deps.store.streamKeyOwner(hashToken(k));
179	      // A press key belongs in a bot's settings, never in a scene.
180	      if (!owner || owner.kind !== "watch") return { statusCode: 401, body: "not a key for watching" };
181	      const named = (event.queryStringParameters?.["run"] ?? "").trim();
182	      const { sessions } = await deps.store.manifest(owner.sub);
183	      const live = sessions
184	        .filter((p) => p.role === "owner" && !p.deletedAt && !p.endedAt && (!named || p.id === named))
185	        .sort((a, b) => (a.updatedAt < b.updatedAt ? 1 : a.updatedAt > b.updatedAt ? -1 : 0));
186	      let watching: string | null = null;
187	      for (const p of live)
188	        if ((await deps.store.getSession(p.id))?.meta.publicTokenHash) {
189	          watching = p.id;
190	          break;
191	        }
192	      if (!watching) return { statusCode: 401, body: "no run is open to watch" };
193	      const who = `stream:${owner.sub}`;
194	      const attached = attachedOf(event, watching);
195	      await deps.live.connect(connectionId, who, now(), attached);
196	      await deps.live.watch(connectionId, watching, who, now(), attached);
197	      return { statusCode: 200 };
198	    }
199	    const token = event.queryStringParameters?.["token"];
200	    let caller: Caller;
201	    try {
202	      caller = await deps.verify(token ? `Bearer ${token}` : undefined);
203	    } catch {
204	      return { statusCode: 401, body: "sign in first" };
205	    }
206	    const deck = deckOf(event);
207	    await deps.live.connect(connectionId, caller.sub, now(), deck);
208	    if (deck) await tellDecks(caller.sub, connectionId);
209	    return { statusCode: 200 };
210	  }
211	
212	  /**
213	   * Who has a tool on the game right now, said to everyone watching.
214	   *
215	   * The whole set every time rather than a joining and a leaving. A table
216	   * that missed one message would otherwise show a tool that went home an
217	   * hour ago, or miss one that is about to be sent a curse, and there is
218	   * no cheap way to notice you missed it. A list is idempotent; a delta is
219	   * a thing to keep in step.
220	   */
221	  const tellWhoIsAttached = async (run: string): Promise<void> => {
222	    const poster = deps.poster;
223	    if (!poster) return;
224	    const watching = await deps.live.watchers(run);
225	    const tools = watching.filter((w) => w.control).map((w) => ({ ...(w.seat ? { seat: w.seat } : {}), ...(w.app ? { app: w.app } : {}) }));
226	    const decks = watching.filter((w) => w.deck).length;
227	    const line = JSON.stringify({ t: "gesture", id: run, kind: "tools", data: { tools, count: tools.length, decks }, at: now() });
228	    for (const w of watching) {
229	      // A tool is told in operations, never in words about itself.
230	      if (w.control) continue;
231	      try {
232	        if ((await poster.post(w.connectionId, line)) === "gone") await deps.live.disconnect(w.connectionId);
233	      } catch (error) {
234	        console.error("live: could not say who is attached", error);
235	      }
236	    }
237	  };
238	
239	  if (routeKey === "$disconnect") {
240	    // Read before it goes: a tool leaving is news, and afterwards there is
241	    // nothing left to say which run it was on.
242	    const leaving = await deps.live.connection(connectionId);
243	    await deps.live.disconnect(connectionId);
244	    if (leaving?.control && leaving.run) await tellWhoIsAttached(leaving.run);
245	    // A deck leaving its run is news the same way a tool leaving is: the
246	    // page is told, as it was told the deck came on.
247	    if (leaving?.deck && leaving.run) await tellWhoIsAttached(leaving.run);
248	    // A page closing may have been the last thing holding a run, and a deck
249	    // whose keys still look live is worse than one that says so.
250	    if (leaving && !leaving.deck && writes(leaving)) await tellDecks(leaving.sub);
251	    return { statusCode: 200 };
252	  }
253	
254	  // $default: a message.
255	  const conn = await deps.live.connection(connectionId);
256	  if (!conn) return { statusCode: 401, body: "unknown connection" };
257	  let message: unknown;
258	  try {
259	    const raw = event.isBase64Encoded ? Buffer.from(event.body ?? "", "base64").toString("utf8") : (event.body ?? "");
260	    message = JSON.parse(raw);
261	  } catch {
262	    return { statusCode: 400, body: "JSON, please" };
263	  }
264	  if (!message || typeof message !== "object") return { statusCode: 400, body: "an object" };
265	  const m = message as Record<string, unknown>;
266	
267	  /**
268	   * A tool saying what it is and what it can do.
269	   *
270	   * The one message an attached tool sends, and the only one any of them
271	   * may: what comes back is the run's own terms, the settings it wants in
272	   * force before anything is rolled. Everything else it hears is sent
273	   * because the table moved, never because it asked.
274	   *
275	   * What the tool can do is not read here. A source that only ever sends
276	   * what a profile names cannot send an operation an old build lacks, and
277	   * a build that receives one refuses it by name, which is the answer in
278	   * both directions.
279	   */
280	  if (conn.control && m["t"] === "hello" && conn.run) {
281	    // What it calls itself is remembered, because a profile written for
282	    // one program must not drive another that happens to share an
283	    // operation name.
284	    const app = typeof m["app"] === "string" ? m["app"].trim().slice(0, 64) : "";
285	    await deps.live.watch(connectionId, conn.run, conn.sub, now(), {
286	      control: true,
287	      ...(conn.seat ? { seat: conn.seat } : {}),
288	      ...(app ? { app } : {}),
289	      run: conn.run,
290	    });
291	
292	    // The table hears that somebody's game is on the other end of this.
293	    // Said here rather than at connect, because until the hello arrives
294	    // there is no seat and no name to say, and a row with neither is not
295	    // worth drawing.
296	    await tellWhoIsAttached(conn.run);
297	
298	    const poster = deps.poster;
299	    if (!poster) return { statusCode: 200 };
300	    const snapshot = await deps.store.getSnapshot(conn.run);
301	    const profile = snapshot ? profileOf(snapshot.snapshot) : null;
302	    // Told rather than left silent: a tool sitting there doing nothing
303	    // is the most confusing thing this could do. Which is what it did
304	    // until now in the one case that matters most, the run it found
305	    // having no rules at all: an address names an account and the
306	    // server picks the run, so a tool can attach perfectly to a run
307	    // nobody is playing and report itself connected for ever.
308	    const session = await deps.store.getSession(conn.run);
309	    const which = session?.meta.packTitle ?? "a run";
310	    /**
311	     * Who has already had the parts of the terms that are given once.
312	     *
313	     * A seat, or the table where a tool named none. The terms go out on
314	     * every attach, because a tool that restarted is holding none of
315	     * them and a setting applied twice is the same setting. A gift is
316	     * not: a run whose terms hand over runes or an item handed them over
317	     * again on every reconnect, and by the third one it is a different
318	     * game. So the run remembers, and those parts are left out.
319	     */
320	    const whose = conn.seat || "the table";
321	    const given = session?.meta.termsGiven ?? [];
322	    const gotLoadout = session?.meta.loadoutGiven ?? [];
323	    /*
324	     * Two effects, not one. The pack's terms and the loadout chosen for
325	     * this run are one list in the profile and go out as two applies,
326	     * because the loadout has a button that re-sends it and a tool
327	     * re-applying an id takes the old one off first.
328	     */
329	    let terms: { frame: string; gave: boolean } | null = null;
330	    let loadout: { frame: string; gave: boolean } | null = null;
331	    const lines: string[] = [];
332	    if (!profile) {
333	      lines.push(
334	        JSON.stringify({
335	          t: "note",
336	          text: `Attached to ${which}, which has no rules for a tool. An address finds the most recently played run that is open to watchers; if that is not the one you are playing, open that one to watchers and connect again.`,
337	        }),
338	      );
339	    } else if (!fits(profile, app || undefined)) {
340	      lines.push(
341	        JSON.stringify({
342	          t: "note",
343	          text: `${which} is set up for ${profile.tool}, so nothing here will reach ${app || "a tool that did not say what it is"}.`,
344	        }),
345	      );
346	    } else {
347	      terms = setupFor(profile, given.includes(whose));
348	      loadout = loadoutFor(profile, gotLoadout.includes(whose));
349	      if (terms) lines.push(terms.frame);
350	      if (loadout) lines.push(loadout.frame);
351	    }
352	    for (const line of lines) {
353	      if ((await poster.post(connectionId, line)) === "gone") {
354	        await deps.live.disconnect(connectionId);
355	        return { statusCode: 200 };
356	      }
357	    }
358	    // Remembered only once it has actually gone out. A post that failed
359	    // is a tool that never got its terms, and marking it given would
360	    // leave the next attach short of them for the rest of the run.
361	    const patch: { termsGiven?: string[]; loadoutGiven?: string[] } = {};
362	    if (terms?.gave && !given.includes(whose)) patch.termsGiven = [...given, whose];
363	    if (loadout?.gave && !gotLoadout.includes(whose)) patch.loadoutGiven = [...gotLoadout, whose];
364	    if (patch.termsGiven || patch.loadoutGiven) await deps.store.updateSession(conn.run, now(), patch);
365	    return { statusCode: 200 };
366	  }
367	
368	  /**
369	   * A tool saying what happened in the game.
370	   *
371	   * The one thing that travels the other way. It is a mention rather than
372	   * a command: it becomes an ask, exactly as a viewer pressing a button
373	   * does, and the table still decides. Which is why this needs the host
374	   * to have switched asks on, and is refused as politely as anything else
375	   * when they have not.
376	   */
377	  if (conn.control && m["t"] === "event" && conn.run) {
378	    /**
379	     * Something the game said. Dropped for several good reasons, and it
380	     * used to be dropped in silence: every one of these answered 200, the
381	     * tool logged that it had said so, and a death counted nowhere. The
382	     * tool is told now, because "it went nowhere and here is why" is the
383	     * one thing it cannot work out from its end.
384	     */
385	    const drop = async (why: string): Promise<WsResult> => {
386	      const poster = deps.poster;
387	      if (poster) {
388	        try {
389	          await poster.post(connectionId, JSON.stringify({ t: "note", text: why }));
390	        } catch (error) {
391	          console.error("live: could not say why an event went nowhere", error);
392	        }
393	      }
394	      return { statusCode: 200 };
395	    };
396	    const meant = askFor(String(m["kind"] ?? ""));
397	    if (!meant) return drop(`This run has nothing it calls "${String(m["kind"] ?? "")}", so nothing was counted.`);
398	    const session = await deps.store.getSession(conn.run);
399	    if (!session || session.meta.deletedAt || session.meta.endedAt) return drop("That run has ended, so nothing was counted.");
400	    // Taking asks stays the host's word, per run, the same as it is for
401	    // chat. A tool cannot switch it on by being attached.
402	    if (!session.meta.askPolicy)
403	      return drop(
404	        "This run is not taking asks, so nothing was counted. Switch it on under Settings, Stream, Chat, and the game's word counts from then on.",
405	      );
406	    const who = conn.seat || "the game";
407	    const at = now();
408	    if (!askAllowed(conn.run, who, Date.parse(at)).ok) return drop("Too many, too quickly: this one was not counted.");
409	    const ask: Ask = { id: randomBytes(6).toString("hex"), kind: "move", move: meant.move, name: who, via: "the game", at };
410	    await deps.store.addAsk(conn.run, ask);
411	    const poster = deps.poster;
412	    // And when it did land, which of the two landings it was: taken, or
413	    // put in front of somebody. A tool that cannot tell those apart from
414	    // having been ignored is a tool nobody believes.
415	    if (poster) {
416	      const heard =
417	        session.meta.askPolicy === "auto" ? "Counted." : "Said. It is in the run's asks, waiting for whoever is at the table to take it.";
418	      try {
419	        await poster.post(connectionId, JSON.stringify({ t: "note", text: heard }));
420	      } catch (error) {
421	        console.error("live: could not say an event landed", error);
422	      }
423	    }
424	    if (poster) {
425	      const line = JSON.stringify({
426	        t: "gesture",
427	        id: conn.run,
428	        kind: "ask",
429	        data: { ask: ask.id, kind: ask.kind, move: ask.move, name: who, via: ask.via, policy: session.meta.askPolicy },
430	        at,
431	      });
432	      for (const w of await deps.live.watchers(conn.run)) {
433	        if (w.control) continue;
434	        try {
435	          if ((await poster.post(w.connectionId, line)) === "gone") await deps.live.disconnect(w.connectionId);
436	        } catch (error) {
437	          console.error("live: could not pass an ask on", error);
438	        }
439	      }
440	    }
441	
442	    return { statusCode: 200 };
443	  }
444	
445	  /**
446	   * A deck pressing something.
447	   *
448	   * The server checks who is asking and finds the devices that could take
449	   * it; it does not read the press. What may be pressed is the run's
450	   * business, and the run is the only thing holding the pack and the log.
451	   *
452	   * Nothing is stored. A press is worth exactly as much as the moment it
453	   * was made in: `seq` names the offer it was drawn from, and the writing
454	   * device refuses one it has already moved past. Durability would buy a
455	   * press that lands after the reason for it has gone.
456	   */
457	  if (conn.deck && m["t"] === "drive") {
458	    const poster = deps.poster;
459	    const ref = typeof m["ref"] === "string" ? m["ref"].slice(0, 64) : "";
460	    const run = typeof m["run"] === "string" ? m["run"] : "";
461	    const refuse = async (say: string): Promise<WsResult> => {
462	      if (poster) {
463	        try {
464	          await poster.post(connectionId, JSON.stringify({ t: "drove", ref, ok: false, say }));
465	        } catch (error) {
466	          console.error("live: could not refuse a press", error);
467	        }
468	      }
469	      return { statusCode: 200 };
470	    };
471	    if (!ref || !run) return { statusCode: 400, body: "a press has a run and a ref" };
472	    const session = await deps.store.getSession(run);
473	    if (!session || session.meta.deletedAt || session.meta.ownerSub !== conn.sub) return refuse("That run is not yours to press.");
474	    if (session.meta.endedAt) return refuse("That run has ended.");
475	    if (deps.entitled && !(await deps.entitled(conn.sub))) return refuse("Driving a run from a deck is part of Plus.");
476	
477	    const writers = (await deps.live.watchers(run)).filter(writes);
478	    if (writers.length === 0) return refuse("Nothing is holding that run.");
479	    if (!poster) return { statusCode: 200 };
480	
481	    const line = JSON.stringify({
482	      t: "drive",
483	      from: connectionId,
484	      run,
485	      seq: typeof m["seq"] === "number" ? m["seq"] : 0,
486	      ref,
487	      press: String(m["press"] ?? ""),
488	      ...(typeof m["move"] === "string" ? { move: m["move"] } : {}),
489	      ...(m["answer"] && typeof m["answer"] === "object" ? { answer: m["answer"] } : {}),
490	    });
491	    for (const w of writers) {
492	      try {
493	        if ((await poster.post(w.connectionId, line)) === "gone") await deps.live.disconnect(w.connectionId);
494	      } catch (error) {
495	        console.error("live: could not pass a press on", error);
496	      }
497	    }
498	    return { statusCode: 200 };
499	  }
500	
501	  /**
502	   * The verdict, on its way back to the one deck that asked.
503	   *
504	   * The deck's connection id came out with the press and goes back with
505	   * the answer, so the server keeps no record of who asked for what. It is
506	   * checked before it is posted to: a member may only answer a deck of
507	   * their own account.
508	   */
509	  if (m["t"] === "drove" && typeof m["to"] === "string") {
510	    // A link's socket and a scene's have no account of their own to share
511	    // with a deck, so no `sub` of theirs can ever match one; said outright
512	    // rather than left to fall out of the comparison below.
513	    if (conn.sub.startsWith("public:") || conn.sub.startsWith("stream:")) return { statusCode: 200 };
514	    const poster = deps.poster;
515	    if (!poster) return { statusCode: 200 };
516	    const target = await deps.live.connection(m["to"]);
517	    if (!target || !target.deck || target.sub !== conn.sub) return { statusCode: 200 };
518	    const line = JSON.stringify({
519	      t: "drove",
520	      ref: typeof m["ref"] === "string" ? m["ref"] : "",
521	      ok: m["ok"] === true,
522	      ...(typeof m["say"] === "string" ? { say: m["say"] } : {}),
523	    });
524	    try {
525	      if ((await poster.post(m["to"], line)) === "gone") await deps.live.disconnect(m["to"]);
526	    } catch (error) {
527	      console.error("live: could not pass a verdict back", error);
528	    }
529	    return { statusCode: 200 };
530	  }
531	
532	  // A link's socket, and a scene's, watch the one run they were opened for
533	  // and take no requests.
534	  if (conn.sub.startsWith("public:") || conn.sub.startsWith("stream:")) return { statusCode: 200 };
535	  // A gesture: something happening at the table that is not a move, dice
536	  // in the air, a step opened, a card turned, passed straight on to
537	  // everyone watching the run and kept nowhere. Only a member sends one,
538	  // it is small, and its kind is a short word the app gives meaning to.
539	  if (m["t"] === "gesture" && typeof m["id"] === "string" && typeof m["kind"] === "string") {
540	    const id = m["id"];
541	    const kind = m["kind"];
542	    if (id.length > 200 || !/^[a-z][a-z0-9-]{0,31}$/.test(kind)) return { statusCode: 400, body: "a gesture has an id and a kind" };
543	    const data = m["data"] !== undefined && typeof m["data"] === "object" && m["data"] !== null ? m["data"] : {};
544	    if (JSON.stringify(data).length > 2000) return { statusCode: 400, body: "a gesture is small" };
545	    const session = await deps.store.getSession(id);
546	    const member = session && !session.meta.deletedAt ? session.members.find((x) => x.sub === conn.sub) : undefined;
547	    if (!member) return { statusCode: 200 };
548	    const line = JSON.stringify({ t: "gesture", id, kind, data, ...(member.name ? { from: member.name } : {}), at: now() });
549	    const poster = deps.poster;
550	
551	    /**
552	     * The loadout, handed out again on purpose.
553	     *
554	     * Every other gesture is passed on. This one means something to the
555	     * server, because the thing standing in the way of handing a loadout
556	     * out twice is a record the server keeps.
557	     *
558	     * `loadoutGiven` exists so that a tool which dropped and reconnected
559	     * is not given the runes again, and it has to go on doing that. But
560	     * a run whose host has picked a different loadout and pressed the
561	     * button is not a reconnect; it is somebody deciding that this table
562	     * is playing with different gear from now on. So the record is
563	     * cleared here and rebuilt from what actually goes out, and a
564	     * reconnect a second later is short of the gifts exactly as before.
565	     *
566	     * The loadout only. The pack's terms are a separate effect and are
567	     * not re-sent: the button is under a list of loadouts and says it
568	     * hands out the loadout, and sending the terms with it handed over
569	     * the pack's own gifts a second time as well.
570	     *
571	     * The owner only. Every member can send a gesture, and that is right
572	     * for dice in the air and a step opening; handing somebody a hundred
573	     * and twenty thousand runes is not something one player at the table
574	     * should be able to do to the others.
575	     *
576	     * Asked of the run rather than of the member row. Both say the same
577	     * thing today, and the run is the one that says it first: a member
578	     * row carries whatever was written into it when somebody joined.
579	     */
580	    if (kind === "setup") {
581	      if (session?.meta.ownerSub !== conn.sub) return { statusCode: 200 };
582	      if (!poster) return { statusCode: 200 };
583	      const watchers = await deps.live.watchers(id);
584	      const attached = watchers.filter((w) => w.control);
585	      const profile = attached.length > 0 ? profileOf((await deps.store.getSnapshot(id))?.snapshot) : null;
586	      const gave: string[] = [];
587	      await Promise.all(
588	        watchers.map(async (w) => {
589	          // The table is told in words that it happened; a tool is told
590	          // in operations, which is the same split as everywhere else.
591	          let out = w.connectionId === connectionId ? null : line;
592	          if (w.control) {
593	            if (!profile || !fits(profile, w.app)) return;
594	            // `false`, because being handed one is the whole point: the
595	            // record that would hold the gifts back has just been dropped.
596	            const loadout = loadoutFor(profile, false);
597	            if (!loadout) return;
598	            out = loadout.frame;
599	            if (loadout.gave) gave.push(w.seat || "the table");
600	          }
601	          if (!out) return;
602	          try {
603	            if ((await poster.post(w.connectionId, out)) === "gone") await deps.live.disconnect(w.connectionId);
604	          } catch (error) {
605	            console.error("live: could not hand out the setup", error);
606	          }
607	        }),
608	      );
609	      // Written after the fact, from what went out rather than from what
610	      // was meant to: a tool that was not reachable did not get its
611	      // loadout, and saying it did would leave it short on the next
612	      // attach. `termsGiven` is left alone, because the terms did not
613	      // move.
614	      await deps.store.updateSession(id, now(), { loadoutGiven: [...new Set(gave)] });
615	      return { statusCode: 200 };
616	    }
617	
618	    if (poster) {
619	      const watchers = (await deps.live.watchers(id)).filter((w) => w.connectionId !== connectionId);
620	      // A tool attached to somebody's game is told in operations rather
621	      // than in words, and the profile that decides which is read only
622	      // when one of them is listening.
623	      const attached = watchers.filter((w) => w.control);
624	      const profile = attached.length > 0 ? profileOf((await deps.store.getSnapshot(id))?.snapshot) : null;
625	      await Promise.all(
626	        watchers.map(async (w) => {
627	          const lines = !w.control ? [line] : profile && fits(profile, w.app) ? framesForGesture(profile, kind, data, w.seat) : [];
628	          for (const out of lines) {
629	            try {
630	              if ((await poster.post(w.connectionId, out)) === "gone") {
631	                await deps.live.disconnect(w.connectionId);
632	                return;
633	              }
634	            } catch (error) {
635	              console.error("live: could not pass a gesture on", error);
636	            }
637	          }
638	        }),
639	      );
640	    }
641	    return { statusCode: 200 };
642	  }
643	  if (m["t"] === "watch" && typeof m["id"] === "string" && m["id"].length > 0 && m["id"].length <= 200) {
644	    // A session or a race that is not theirs to see looks exactly like one
645	    // that is not there: the socket confirms nothing.
646	    const session = await deps.store.getSession(m["id"]);
647	    const inSession = Boolean(session && !session.meta.deletedAt && session.members.some((x) => x.sub === conn.sub));
648	    const race = inSession ? null : await deps.races.getRace(m["id"]);
649	    const inRace = Boolean(race && race.entries.some((e) => e.sub === conn.sub));
650	    if (!inSession && !inRace) return { statusCode: 200 };
651	    await deps.live.watch(connectionId, m["id"], conn.sub, now(), conn.deck ? { deck: true, run: m["id"] } : undefined);
652	    if (conn.deck) {
653	      // A deck is told a run is on it the same way a page is told a tool
654	      // is: the row says so, and the table hears it.
655	      await deps.live.connect(connectionId, conn.sub, now(), { deck: true, run: m["id"] });
656	      await tellWhoIsAttached(m["id"]);
657	    }
658	    // A run just came under a device. A deck that has been sitting on "No
659	    // run open" all evening is the one thing waiting to hear it.
660	    await tellDecks(conn.sub);
661	    return { statusCode: 200 };
662	  }
663	  return { statusCode: 400, body: "unknown message" };
664	}
665	
666	/* ---- the Lambda ---------------------------------------------------------- */
667	
668	let deps: WsDeps | undefined;
669	
670	export async function handler(event: WsEvent): Promise<WsResult> {
671	  if (!deps) {
672	    const clientId = process.env["WORKOS_CLIENT_ID"] ?? "";
673	    const cliClientId = process.env["WORKOS_CLI_CLIENT_ID"] ?? "";
674	    const table = process.env["TABLE_NAME"] ?? "";
675	    const gates = process.env["RUNLOG_GATES"] === "on";
676	    const plusFeature = featuresFromEnv(process.env["STRIPE_FEATURES"]).plus;
677	    const billing = dynamoBilling({ table });
678	    deps = {
679	      live: dynamoLive({ table }),
680	      store: dynamoStore({ table, bucket: process.env["BUCKET_NAME"] ?? "" }),
681	      races: dynamoRaces({ table }),
682	      verify: (authorization) => verifyToken(authorization, [clientId, cliClientId]),
683	      ...(process.env["WS_ENDPOINT"] ? { poster: apiGatewayPoster(process.env["WS_ENDPOINT"]) } : {}),
684	      // No token flags are in hand at drive time, only `conn.sub`: the
685	      // kept flags `billing.flags(sub)` do the work a token flag would on
686	      // the API side, and `/api/me` refreshes those on every call the app
687	      // makes, so a comped account is comped here too.
688	      ...(gates ? { entitled: async (sub: string) => (await grantsOf(billing, sub)).includes(plusFeature) } : {}),
689	    };
690	  }
691	  try {
692	    return await route(event, deps);
693	  } catch (error) {
694	    console.error(error);
695	    return { statusCode: 500, body: "something went wrong on this side" };
696	  }
697	}
